#[allow(clippy::too_many_arguments)]
pub(crate) fn prover_blocks_in(walk: &mut ProverWalk, expr: &Expr, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    match expr {
        Expr::Block(block, _) => { if prover_claims_then_value(block, words) { prover_block(walk, block, &mut scope.clone(), &at.inside(false), program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); } else { prover_nested(walk, block, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); } },
        Expr::Unsafe(block, _) => { prover_nested(walk, block, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); },
        Expr::Overlap(block, _) => { prover_nested(walk, block, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); },
        Expr::Closure { params, mutable, body, .. } => {
            let mut names: Vec<String> = vec![];
            for p in params.iter() {
                let p = *p;
                names.push(words.resolve(p).to_owned());
            }
            for p in mutable.iter() {
                let p = *p;
                names.push(words.resolve(p).to_owned());
            }
            prover_nested(walk, body, Some(names), scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
        },
        Expr::Call { func, args, config, .. } => {
            let func = nikaia_std::boxed::open(func);
            prover_blocks_in(walk, func, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
            for arg in args.iter() { prover_blocks_in(walk, arg, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); }
            for c in config.iter() { prover_blocks_in(walk, &c.value, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            prover_blocks_in(walk, receiver, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
            for arg in args.iter() { prover_blocks_in(walk, arg, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); }
            for c in config.iter() { prover_blocks_in(walk, &c.value, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            prover_blocks_in(walk, receiver, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
            for arg in args.iter() { prover_blocks_in(walk, arg, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); }
            for c in config.iter() { prover_blocks_in(walk, &c.value, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            prover_nested(walk, then_branch, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
            prover_nested_maybe(walk, (else_branch).as_ref(), scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
        },
        Expr::TryCatch { expr, handler, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            prover_blocks_in(walk, expr, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
            prover_nested(walk, handler, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { prover_blocks_in(walk, &arm.body, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); } },
        Expr::Select(arms, _) => { for arm in arms.iter() { prover_nested(walk, &arm.body, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition); } },
        _ => { },
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn prover_nested_maybe(walk: &mut ProverWalk, block: Option<&Block>, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    let present = match block { Some(__nikaia_value) => __nikaia_value, None => return };
    prover_nested(walk, present, None, scope, at, program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn prover_nested(walk: &mut ProverWalk, block: &Block, lambda: Option<Vec<String>>, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    let is_lambda = lambda.is_some();
    if is_lambda {
        let mut inner = scope.clone();
        for param in nikaia_std::index::or(lambda, || vec![].into()) {
            inner.rebind(&walk.arena, &param);
            inner.loose.insert(param.to_owned());
        }
        inner.path = None;
        inner.exact = false;
        prover_block(walk, block, &mut inner, &at.inside(true), program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
    } else {
        let mut inner = scope.blind();
        prover_block(walk, block, &mut inner, &at.inside(false), program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, condition);
    }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn prover_a_call(walk: &mut ProverWalk, callee: &str, args: &[Expr], config: &[ConfigArg], span: Span, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    if scope.locals.contains(callee) { return; }
    let caller = carrying_function((at.function).as_deref());
    if caller.is_some() { walk.state.edges.insert((nikaia_std::index::or(caller, || "".into()), callee.to_owned())); }
    let pre = if walk.state.collecting { prover_precondition_in(&walk.state.known, callee) } else { prover_precondition_in(&walk.state.preconditions, callee) };
    if pre.is_some() {
        let function = match free_function(program, words, callee) { Some(__nikaia_value) => __nikaia_value, None => return };
        let found = nikaia_std::index::or(pre, || Precondition::none());
        let all = arguments_in_order(&function, args, config, words);
        prover_record_call(walk, callee, &function.params, &found.claims, &all, span, scope, at, words, ask, model, escape, written_of);
        return;
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return };
    if !foreign.requires.is_empty() { prover_record_call(walk, callee, &foreign.params, &foreign.requires, args, span, scope, at, words, ask, model, escape, written_of); }
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn prover_a_method_call(walk: &mut ProverWalk, receiver: &Expr, method: winnow_grammar::Symbol, args: &[Expr], config: &[ConfigArg], span: Span, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String) {
    if nikaia_std::index::or(prover_variable_named(Some(receiver), words), || "".into()) != "self" { return; }
    let function = match carrying_function((at.function).as_deref()) { Some(__nikaia_value) => __nikaia_value, None => return };
    let cut = match nikaia_std::search::rfind(&function, &"::") { Some(__nikaia_value) => __nikaia_value, None => return };
    let owner = nikaia_std::index::get(&function, nikaia_std::index::at(0..cut)).to_owned();
    let name = words.resolve(method).to_owned();
    let callee = format!("{}::{}", owner, name);
    walk.state.edges.insert((function.to_owned(), callee.to_owned()));
    let pre = if walk.state.collecting { prover_precondition_in(&walk.state.known, &callee) } else { prover_precondition_in(&walk.state.preconditions, &callee) };
    let found = match pre { Some(__nikaia_value) => __nikaia_value, None => return };
    let target = match own_method(program, words, &owner, &name) { Some(__nikaia_value) => __nikaia_value, None => return };
    let all = arguments_in_order(&target, args, config, words);
    prover_record_call(walk, &callee, &target.params, &found.claims, &all, span, scope, at, words, ask, model, escape, written_of);
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn prover_record_call(walk: &mut ProverWalk, callee: &str, params: &[String], claims: &[PreClaim], args: &[Expr], span: Span, scope: &ProverScope, at: &ProverWhere, words: &winnow_grammar::InternerContext, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String) {
    let outcome = walk.state.precondition_call(&mut walk.arena, words, callee, params, claims, args, span, scope, at, ask, model, escape);
    for found in outcome.findings.iter() { walk.findings.push(found.clone()); }
    let mut written: String = String::from("");
    for arg in args.iter() {
        if !written.is_empty() { written.push_str(", "); }
        written.push_str(&written_of(arg));
    }
    let key = (callee.to_owned(), written);
    let before = walk.reaches.remove(&key);
    if before.is_some() { walk.reaches.insert(key, joined_reach(nikaia_std::index::or(before, || CallReach::Proved), outcome.reach)); } else { walk.reaches.insert(key, outcome.reach); }
}

pub(crate) fn prover_foreign_contract(walk: &mut ProverWalk, key: &str, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> Option<Foreign> {
    let cached = prover_cached_foreign(&walk.state.foreign, key);
    if cached.is_some() { return std::convert::identity(cached); }
    let contract = match *nikaia_std::index::get(&own.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let shape = foreign_shape(contract);
    let mut requires: Vec<i64> = vec![];
    for text in contract.requires.iter() { requires.push(prover_condition_term(&mut walk.arena, text, &shape.names, condition)); }
    let mut ensures: Vec<i64> = vec![];
    for text in contract.ensures.iter() { ensures.push(prover_condition_term(&mut walk.arena, text, &shape.names, condition)); }
    let foreign = foreign_from(contract, shape, &requires, &ensures);
    walk.state.foreign.insert(key.to_owned(), Some(foreign.clone()));
    Some(foreign)
}

pub(crate) fn prover_condition_term(arena: &mut TermArena, text: &str, names: &collections::BTreeSet<String>, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> i64 {
    let nodes = condition(text, names);
    if nodes.is_empty() { return -1; }
    arena.adopt((nodes).as_ref())
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn prover_postconditions_of(walk: &mut ProverWalk, callee: &str, args: &[Expr], config: &[ConfigArg], bound: &str, scope: &ProverScope, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> Vec<i64> {
    let posts = standing_posts(&walk.state.postconditions, callee);
    if posts.is_some() {
        let function = match free_function(program, words, callee) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
        let all = arguments_in_order(&function, args, config, words);
        return postconditions_for(&mut walk.arena, &nikaia_std::index::or(posts, || vec![].into()), &function.params, &all, bound, scope, words, &walk.state.pinned);
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    postconditions_for(&mut walk.arena, &foreign.ensures, &foreign.params, args, bound, scope, words, &walk.state.pinned)
}

pub(crate) fn prover_returns_whole(walk: &mut ProverWalk, callee: &str, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> bool {
    let function = free_function(program, words, callee);
    if function.is_some() {
        let found = match function { Some(__nikaia_value) => __nikaia_value, None => return false };
        return found.whole_result;
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return false };
    foreign.whole_result
}

pub(crate) fn prover_throws(call: &Expr, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, unaliased: &impl Fn(&str) -> String) -> bool { may_throw(call, at.throws_out, program, words, own, library, unaliased) }

pub(crate) fn prover_called(func: &Expr, words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match func {
        Expr::Variable(name, _) => { let name = *name; Some(words.resolve(name).to_owned()) },
        Expr::Path(segments, _) => Some(prover_qualified(segments, words, unaliased)),
        _ => None,
    }
}

pub(crate) fn prover_bound_callee(func: &Expr, scope: &ProverScope, words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match func {
        Expr::Variable(name, _) => {
            let name = *name;
            let text = words.resolve(name);
            if scope.locals.contains(text) { return None; }
            Some(text.to_owned())
        },
        Expr::Path(segments, _) => Some(prover_qualified(segments, words, unaliased)),
        _ => None,
    }
}

pub(crate) fn prover_qualified(segments: &[winnow_grammar::Symbol], words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> String {
    let mut joined: String = String::from("");
    for segment in segments.iter() {
        let segment = *segment;
        if !joined.is_empty() { joined.push_str("::"); }
        joined.push_str(words.resolve(segment));
    }
    unaliased(&joined)
}

pub fn prover_an_assert_call(func: &Expr, args: &[Expr], span: &Span, claims: &collections::BTreeSet<(i64, i64)>) -> bool {
    let named = matches!(func, Expr::Variable(_, _));
    if !named || args.len() != 1 { return false; }
    claims.contains(&(span.start as i64, node_key(nikaia_std::index::get(&args, 0))))
}

pub fn prover_assumed_in_unsafe(block: &Block, words: &winnow_grammar::InternerContext) -> Vec<Expr> {
    let mut out: Vec<Expr> = vec![];
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Expr(inner) => {
                match inner {
                    Expr::Call { func, args, .. } => {
                        let func = nikaia_std::boxed::open(func);
                        if !prover_an_assume(func, words) || args.len() != 1 { return vec![]; }
                        out.push((*nikaia_std::index::get(&args, 0)).clone());
                    },
                    _ => { return vec![]; },
                }
            },
            _ => { return vec![]; },
        }
    }
    out
}

pub fn prover_an_assume(func: &Expr, words: &winnow_grammar::InternerContext) -> bool {
    match func {
        Expr::Variable(name, _) => { let name = *name; words.resolve(name) == "assume" },
        _ => false,
    }
}

pub(crate) fn prover_a_given_rule(config: &[ConfigArg], words: &winnow_grammar::InternerContext) -> bool {
    for option in config.iter() { if words.resolve(option.name) == "rule of the type" { return true; } }
    false
}

pub(crate) fn prover_message(config: &[ConfigArg], words: &winnow_grammar::InternerContext) -> Option<String> {
    for c in config.iter() {
        if words.resolve(c.name) == "message" {
            match &c.value {
                Expr::LitStr { text, .. } => { return Some(text.to_owned()); },
                _ => { },
            }
        }
    }
    None
}

pub(crate) fn prover_a_claim_stmt(stmt: &Stmt, words: &winnow_grammar::InternerContext) -> bool {
    match stmt {
        Stmt::Expr(inner) => match inner {
            Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); args.len() == 1 && nikaia_std::index::or(prover_variable_named(Some(func), words), || "".into()) == "assert" },
            _ => false,
        },
        _ => false,
    }
}

pub(crate) fn prover_claims_then_value(block: &Block, words: &winnow_grammar::InternerContext) -> bool {
    let last = block.stmts.len() as i64 - 1;
    if last < 0 { return false; }
    for k in 0..last { if !prover_a_claim_stmt(&nikaia_std::index::get(&block.stmts, (k) as usize).node, words) { return false; } }
    matches!(nikaia_std::index::get(&block.stmts, nikaia_std::index::at(last)).node, Stmt::Expr(_))
}

pub(crate) fn prover_returned_name(stmt: &Stmt, words: &winnow_grammar::InternerContext) -> Option<String> {
    match stmt {
        Stmt::Return(value) => prover_variable_named((value).as_ref(), words),
        _ => None,
    }
}

pub(crate) fn prover_variable_named(value: Option<&Expr>, words: &winnow_grammar::InternerContext) -> Option<String> {
    let present = match value { Some(__nikaia_value) => __nikaia_value, None => return None };
    match present {
        Expr::Variable(name, _) => { let name = *name; Some(words.resolve(name).to_owned()) },
        _ => None,
    }
}

pub(crate) fn prover_assigned(walk: &mut ProverWalk, n: &str, op: Option<&BinaryOp>, value: &Expr, span: &Span, scope: &mut ProverScope, words: &winnow_grammar::InternerContext) -> bool {
    if !scope.mutables.contains(n) { return false; }
    let read = match lin_term(value, words, &|name| { scope.ints.contains(name) }, &|name| { prover_pinned(&walk.state.pinned, &scope, name) }, &mut walk.arena.nodes) { Some(__nikaia_value) => __nikaia_value, None => return false };
    let mut term = read;
    if op.is_some() {
        if !scope.ints.contains(n) { return false; }
        let old = walk.arena.var(n);
        let written = match op { Some(__nikaia_value) => __nikaia_value, None => return false };
        term = match written {
            BinaryOp::Add => walk.arena.add(old, read),
            BinaryOp::Sub => walk.arena.sub(old, read),
            BinaryOp::Mul => {
                if walk.arena.constant(read).is_none() { return false; }
                walk.arena.mul(old, read)
            },
            _ => return false,
        };
    }
    if walk.arena.mentions(term, n) {
        let known = prover_known_value(&walk.arena, &scope.facts, n);
        if known.is_some() {
            let mut pinned: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
            pinned.insert(n.to_owned(), walk.arena.int(nikaia_std::index::or(known, || 0)));
            term = walk.arena.substitute(term, &pinned);
            let folded = walk.arena.constant(term);
            if folded.is_some() { term = walk.arena.int(nikaia_std::index::or(folded, || 0)); }
        }
    }
    prover_assign_term(walk, n, term, &span, scope);
    true
}

pub(crate) fn prover_assign_term(walk: &mut ProverWalk, n: &str, term: i64, span: &Span, scope: &mut ProverScope) {
    let at_entry = scope.at_entry(&mut walk.arena, term);
    let mut read_names: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(term, &mut read_names);
    let mut loose = false;
    for name in read_names.iter() { if scope.loose.contains(name) { loose = true; } }
    let earlier = format!("{}#{}", n, span.start);
    scope.renamed(&mut walk.arena, n, &earlier);
    let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    given.insert(n.to_owned(), walk.arena.var(&earlier));
    let over = walk.arena.substitute(term, &given);
    let named = walk.arena.var(n);
    let fact = walk.arena.equal(named, over);
    let mut over_names: collections::BTreeSet<String> = collections::BTreeSet::new();
    walk.arena.variables(over, &mut over_names);
    let mut earlier_read = false;
    for name in over_names.iter() { if name.contains('#') { earlier_read = true; } }
    if earlier_read { scope.history.push(fact); } else { scope.facts.push(fact); }
    scope.ints.insert(n.to_owned());
    if loose { scope.loose.insert(n.to_owned()); }
    if at_entry.is_some() { scope.entry.insert(n.to_owned(), nikaia_std::index::or(at_entry, || 0)); }
}

pub(crate) fn prover_known_value(arena: &TermArena, facts: &[i64], n: &str) -> Option<i64> {
    for fact in facts.iter() {
        let fact = nikaia_std::num::value(fact);
        match arena.at(fact) {
            SolverTerm::Eq(a, b) => {
                if arena.is_the_variable(a, n) {
                    let value = arena.constant(b);
                    if value.is_some() { return std::convert::identity(value); }
                }
            },
            _ => { },
        }
    }
    None
}

pub(crate) fn prover_binds_mutable(block: &Block) -> bool {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { names, mutable, .. } => {
                let mutable = *mutable;
                if mutable && names.len() == 1 { return true; }
            },
            _ => { },
        }
    }
    false
}

pub(crate) fn prover_follow_mutables(walk: &mut ProverWalk, stmt: &Stmt, span: &Span, scope: &mut ProverScope, untracked: &collections::BTreeSet<String>, pinned: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext) {
    prover_follow_lengths(walk, stmt, &span, scope, words);
    match stmt {
        Stmt::Let { names, mutable, ty, value, .. } => {
            let mutable = *mutable;
            if mutable && names.len() == 1 {
                let n = words.resolve(*nikaia_std::index::get(&names, 0)).to_owned();
                if !pinned.contains(&n) { prover_mutable_list(walk, &n, (ty).as_ref(), value, scope, words); }
                if !untracked.contains(&n) {
                    let term = lin_term(value, words, &|name| { scope.ints.contains(name) }, &|name| { prover_pinned(&walk.state.pinned, &scope, name) }, &mut walk.arena.nodes);
                    if term.is_some() && !walk.arena.mentions(nikaia_std::index::or(term, || 0), &n) {
                        let v = nikaia_std::index::or(term, || 0);
                        let at_entry = scope.at_entry(&mut walk.arena, v);
                        scope.ints.insert(n.to_owned());
                        scope.mutables.insert(n.to_owned());
                        let named = walk.arena.var(&n);
                        scope.facts.push(walk.arena.equal(named, v));
                        if at_entry.is_some() { scope.entry.insert(n.to_owned(), nikaia_std::index::or(at_entry, || 0)); }
                    }
                }
            }
        },
        Stmt::While { .. } => { },
        Stmt::For { .. } => { },
        Stmt::Assign { .. } => { },
        _ => { if !scope.mutables.is_empty() && !prover_an_if(stmt) { for n in assigned_in_statement(stmt, words) { if scope.mutables.contains(&n) { scope.rebind(&walk.arena, &n); } } } },
    }
}

pub(crate) fn prover_mutable_list(walk: &mut ProverWalk, n: &str, ty: Option<&Type>, value: &Expr, scope: &mut ProverScope, words: &winnow_grammar::InternerContext) {
    let length = length_of(n);
    match value {
        Expr::ListLit { items, .. } => {
            let known: Option<i64> = Some(items.len() as i64);
            scope.has_length(&mut walk.arena, n, known);
        },
        Expr::ListRepeat { count, .. } => {
            let count = nikaia_std::boxed::open(count);
            let term = lin_term(count, words, &|name| { scope.ints.contains(name) }, &|name| { prover_pinned(&walk.state.pinned, &scope, name) }, &mut walk.arena.nodes);
            scope.has_length(&mut walk.arena, n, None);
            if term.is_some() && !walk.arena.mentions(nikaia_std::index::or(term, || 0), n) && !walk.arena.mentions(nikaia_std::index::or(term, || 0), &length) {
                let named = walk.arena.var(&length);
                scope.facts.push(walk.arena.equal(named, nikaia_std::index::or(term, || 0)));
                scope.loose.remove(&length);
            }
        },
        _ => {
            let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return };
            if words.resolve(t.name) != "Vec" { return; }
            scope.has_length(&mut walk.arena, n, None);
        },
    }
    scope.mutables.insert(length);
}

pub(crate) fn prover_follow_lengths(walk: &mut ProverWalk, stmt: &Stmt, span: &Span, scope: &mut ProverScope, words: &winnow_grammar::InternerContext) {
    match stmt {
        Stmt::While { .. } => { return; },
        Stmt::For { .. } => { return; },
        _ => { },
    }
    if prover_an_if(stmt) { return; }
    let mut lists: Vec<String> = vec![];
    for m in scope.mutables.iter() { if m.ends_with(".len()") { lists.push(nikaia_std::index::or(m.strip_suffix(".len()"), || "").to_owned()); } }
    for list in lists.iter() {
        if !changes_length_in_statement(stmt, list, &walk.state.readers, words) { continue; }
        if !prover_length_set(walk, stmt, list, &span, scope, words) { prover_forget_length(walk, list, scope); }
    }
}

pub(crate) fn prover_forget_length(walk: &mut ProverWalk, list: &str, scope: &mut ProverScope) {
    let length = length_of(list);
    scope.rebind(&walk.arena, &length);
    scope.has_length(&mut walk.arena, list, None);
}

pub(crate) fn prover_length_set(walk: &mut ProverWalk, stmt: &Stmt, list: &str, span: &Span, scope: &mut ProverScope, words: &winnow_grammar::InternerContext) -> bool {
    let expr = match stmt {
        Stmt::Expr(e) => e,
        _ => return false,
    };
    let length = length_of(list);
    if !scope.ints.contains(&length) { scope.has_length(&mut walk.arena, list, None); }
    match expr {
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let on = match receiver {
                Expr::Variable(name, _) => { let name = *name; words.resolve(name) == list },
                _ => false,
            };
            if !on { return false; }
            let m = words.resolve(method).to_owned();
            if m == "push" && args.len() == 1 {
                let old = walk.arena.var(&length);
                let one = walk.arena.int(1);
                let term = walk.arena.add(old, one);
                ({ let __nikaia_arg2 = prover_pinned_old(walk, &length, term, &scope); prover_assign_term(walk, &length, __nikaia_arg2, &span, scope) });
                return true;
            }
            if m == "clear" && args.is_empty() {
                let zero = walk.arena.int(0);
                prover_assign_term(walk, &length, zero, &span, scope);
                return true;
            }
            if m == "resize" && args.len() == 2 || m == "truncate" && args.len() == 1 {
                let n = match lin_term(nikaia_std::index::get(&args, 0), words, &|name| { scope.ints.contains(name) }, &|name| { prover_pinned(&walk.state.pinned, &scope, name) }, &mut walk.arena.nodes) { Some(__nikaia_value) => __nikaia_value, None => return false };
                if m == "resize" {
                    prover_assign_term(walk, &length, n, &span, scope);
                    return true;
                }
                let earlier = format!("{}#{}", length, span.start);
                scope.renamed(&mut walk.arena, &length, &earlier);
                let mut given: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
                given.insert(length.to_owned(), walk.arena.var(&earlier));
                let bound = walk.arena.substitute(n, &given);
                let old = walk.arena.var(&earlier);
                let named = walk.arena.var(&length);
                let cut = walk.arena.equal(named, bound);
                let shorter = walk.arena.le(bound, old);
                let kept = walk.arena.equal(named, old);
                let longer = walk.arena.le(old, bound);
                let first = walk.arena.and(vec![cut, shorter]);
                let second = walk.arena.and(vec![kept, longer]);
                scope.history.push(walk.arena.or(vec![first, second]));
                scope.ints.insert(length.to_owned());
                scope.not_negative(&mut walk.arena, &length);
                scope.loose.insert(length.to_owned());
                return true;
            }
            false
        },
        _ => false,
    }
}

pub(crate) fn prover_pinned_old(walk: &mut ProverWalk, n: &str, term: i64, scope: &ProverScope) -> i64 {
    let known = match prover_known_value(&walk.arena, &scope.facts, n) { Some(__nikaia_value) => __nikaia_value, None => return term };
    let mut pinned: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    pinned.insert(n.to_owned(), walk.arena.int(known));
    let replaced = walk.arena.substitute(term, &pinned);
    let folded = match walk.arena.constant(replaced) { Some(__nikaia_value) => __nikaia_value, None => return replaced };
    walk.arena.int(folded)
}

pub(crate) fn prover_lengths_changed(changed: &mut collections::BTreeSet<String>, body: &Block, scope: &ProverScope, readers: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext) {
    for m in scope.mutables.iter() {
        if m.ends_with(".len()") {
            let list = nikaia_std::index::or(m.strip_suffix(".len()"), || "").to_owned();
            if changes_length_in(body, &list, readers, words) { changed.insert(m.to_owned()); }
        }
    }
}

pub(crate) fn prover_else_lengths_changed(changed: &mut collections::BTreeSet<String>, else_branch: Option<&Block>, scope: &ProverScope, readers: &collections::BTreeSet<String>, words: &winnow_grammar::InternerContext) {
    let block = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return };
    prover_lengths_changed(changed, block, scope, readers, words);
}

pub(crate) fn prover_loop_keeps(n: &str, changed: &collections::BTreeSet<String>, body: &Block, scope: &ProverScope, words: &winnow_grammar::InternerContext) -> bool {
    let length = length_of(n);
    scope.mutables.contains(&length) && !changed.contains(&length) && !rebinds(body, n, words)
}

pub(crate) fn prover_relength(walk: &mut ProverWalk, n: &str, scope: &mut ProverScope) { if n.ends_with(".len()") && scope.mutables.contains(n) { scope.has_length(&mut walk.arena, &nikaia_std::index::or(n.strip_suffix(".len()"), || "").to_owned(), None); } }

pub(crate) fn prover_an_if(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Expr(expr) => matches!(expr, Expr::If { .. }),
        _ => false,
    }
}

pub(crate) fn prover_symbol_text(symbol: Option<&winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext) -> Option<String> {
    let present = match symbol { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(words.resolve(*present).to_owned())
}

pub(crate) fn prover_typed(ty: Option<&Type>, words: &winnow_grammar::InternerContext, asked: i64) -> bool {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    let name = words.resolve(t.name);
    if asked == 0 { return t.generics.is_empty() && is_whole_number(name); }
    if asked == 1 { return name.starts_with('u'); }
    has_a_length(name)
}

pub(crate) fn prover_a_test_function(name: Option<&str>) -> bool {
    let text = match name { Some(__nikaia_value) => __nikaia_value, None => return false };
    let prefix = "__nikaia_test_";
    if !text.starts_with(prefix) || (text.len() as i64) == prefix.len() as i64 { return false; }
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    for k in 14..c.len() as i64 { if *nikaia_std::index::get(&c, (k) as usize) < '0' || *nikaia_std::index::get(&c, (k) as usize) > '9' { return false; } }
    true
}

pub(crate) fn prover_precondition_in(map: &collections::BTreeMap<String, Precondition>, callee: &str) -> Option<Precondition> {
    let found = match *nikaia_std::index::get(&map, callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(found.clone())
}

pub(crate) fn prover_cached_foreign(map: &collections::BTreeMap<String, Option<Foreign>>, key: &str) -> Option<Foreign> {
    let found = match nikaia_std::index::flat(*nikaia_std::index::get(&map, key)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(found.clone())
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn prover_known_calls(walk: &mut ProverWalk, expr: &Expr, scope: &ProverScope, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> collections::BTreeSet<String> {
    let mut found: collections::BTreeSet<String> = collections::BTreeSet::new();
    for one in visited_in_expr(expr) {
        match one {
            Expr::Call { func, args, config, .. } => {
                let func = nikaia_std::boxed::open(func);
                let callee = prover_bound_callee(func, scope, words, unaliased);
                if callee.is_some() && config.is_empty() {
                    let c = nikaia_std::index::or(callee, || "".into());
                    let mut values: Vec<i64> = vec![];
                    let mut all = true;
                    for arg in args.iter() {
                        let v = folded_whole(arg, words, &|n| { prover_pinned(&walk.state.pinned, scope, n) });
                        if v.is_none() { all = false; } else { values.push(nikaia_std::index::or(v, || 0)); }
                    }
                    if all && prover_returns_whole(walk, &c, program, words, own, condition) {
                        let name = call_result_name(one);
                        walk.state.call_sites.insert(name.to_owned(), one.clone());
                        walk.state.call_args.insert(name.to_owned(), (c.to_owned(), values));
                        found.insert(name);
                    }
                }
            },
            _ => { },
        }
    }
    if scope.calls_of.is_empty() { return found; }
    let read = claim_names_in(expr, words, holes_of);
    for (bound, calls) in scope.calls_of.iter() { if read.contains(bound) { for call in calls.iter() { found.insert(call.to_owned()); } } }
    found
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ProverRan {
    pub(crate) held: ClaimHeld,
    pub(crate) findings: Vec<Finding>,
}

pub(crate) fn prover_claim_ran(walk: &mut ProverWalk, read: &collections::BTreeSet<String>, held: &ClaimHeld, findings: &[Finding], written: &str, span: Span, written_of: &impl Fn(&Expr) -> String) -> ProverRan {
    let mut out = ProverRan { held: held.clone(), findings: vec![] };
    let mut values: Vec<String> = vec![];
    for call in read.iter() {
        let text = written_of(match *nikaia_std::index::get(&walk.state.call_sites, call) { Some(__nikaia_value) => __nikaia_value, None => continue });
        let value = *nikaia_std::index::get(&walk.state.pinned, call);
        if value.is_some() { values.push(format!("`{}` is {}, run while the program was built", text, nikaia_std::index::or(value, || 0))); }
    }
    let joined = values.join("; ");
    for found in findings.iter() {
        let mut one = found.clone();
        if one.code == "NK1207" && !values.is_empty() { one.notes.push(format!("{}.", joined)); }
        out.findings.push(one);
    }
    let open = match prover_open_reason(&held) { Some(__nikaia_value) => __nikaia_value, None => return out };
    if open.starts_with("it is false") { return out; }
    let mut why = open.to_owned();
    for call in read.iter() {
        if (*nikaia_std::index::get(&walk.state.pinned, call)).is_some() { continue; }
        let text = written_of(match *nikaia_std::index::get(&walk.state.call_sites, call) { Some(__nikaia_value) => __nikaia_value, None => continue });
        let stop = *nikaia_std::index::get(&walk.state.stopped, call);
        if stop.is_some() {
            let words_said = nikaia_std::index::or(stop, || "").to_owned();
            if !walk.state.collecting { out.findings.push(Finding { code: String::from("NK1207"), span, message: format!("`{}` stops the program every time it is reached, before `{}` is checked.", text, written), notes: vec![format!("The compiler ran `{}` while the program was built, as the program runs it, and it stopped: {}.", text, words_said)], help: Some(String::from("Fix the call, or the function it calls, as you would fix the program stopping there.")), warning: false, labels: vec![] }); }
            why = format!("{}; `{}` stops the program: {}", why, text, words_said);
            continue;
        }
        let not = *nikaia_std::index::get(&walk.state.not_run, call);
        if not.is_some() {
            let because = nikaia_std::index::or(not, || "").to_owned();
            why = format!("{}; `{}` was not run while the program was built: {}", why, text, lowered_first(&without_full_stops(&because)));
            continue;
        }
        walk.state.wanted.insert(call.to_owned());
    }
    out.held = ClaimHeld::AtRunTime(why);
    out
}

pub(crate) fn prover_open_reason(held: &ClaimHeld) -> Option<String> {
    match held {
        ClaimHeld::AtRunTime(why) => Some(why.to_owned()),
        _ => None,
    }
}

pub(crate) fn prover_bit_range(walk: &mut ProverWalk, expr: &Expr, scope: &ProverScope, words: &winnow_grammar::InternerContext) -> Option<ProverBits> {
    match expr {
        Expr::Binary { op, lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            if *op != BinaryOp::BitAnd { return None; }
            let mut mask = nikaia_std::index::or(prover_constant_of(walk, rhs, scope, words), || -1);
            if mask < 0 { mask = nikaia_std::index::or(prover_constant_of(walk, lhs, scope, words), || -1); }
            if mask < 0 { return None; }
            return Some(ProverBits { lo: 0, hi: mask });
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if !args.is_empty() || words.resolve(method) != "bits_as_i64" { return None; }
            match receiver {
                Expr::Binary { op, rhs, .. } => {
                    let rhs = nikaia_std::boxed::open(rhs);
                    if *op != BinaryOp::Shr { return None; }
                    let k = match prover_constant_of(walk, rhs, scope, words) { Some(__nikaia_value) => __nikaia_value, None => return None };
                    if k < 2 || k > 63 { return None; }
                    let by = 64 - k;
                    let top: i64 = 1 << by;
                    return Some(ProverBits { lo: 0, hi: top - 1 });
                },
                _ => { },
            }
        },
        _ => { },
    }
    None
}

pub(crate) fn prover_constant_of(walk: &mut ProverWalk, expr: &Expr, scope: &ProverScope, words: &winnow_grammar::InternerContext) -> Option<i64> {
    let term = match lin_term(expr, words, &|name| { false }, &|name| { prover_pinned(&walk.state.pinned, scope, name) }, &mut walk.arena.nodes) { Some(__nikaia_value) => __nikaia_value, None => return None };
    walk.arena.constant(term)
}

pub(crate) fn prover_loop_bits(walk: &mut ProverWalk, scope: &ProverScope, changed: &collections::BTreeSet<String>, body: &Block, words: &winnow_grammar::InternerContext) -> collections::BTreeMap<String, ProverBits> {
    let mut out: collections::BTreeMap<String, ProverBits> = collections::BTreeMap::new();
    for n in changed.iter() {
        if !scope.bits.contains_key(n) { continue; }
        let before = match (*nikaia_std::index::get(&scope.bits, n)).copied() { Some(__nikaia_value) => __nikaia_value, None => continue };
        if prover_assigns_inside(walk, body, n, &before, scope, words) { out.insert(n.to_owned(), ProverBits { lo: before.lo, hi: before.hi }); }
    }
    out
}

pub(crate) fn prover_assigns_inside(walk: &mut ProverWalk, block: &Block, name: &str, bounds: &ProverBits, scope: &ProverScope, words: &winnow_grammar::InternerContext) -> bool {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Assign { target, op, value } => {
                match target {
                    Expr::Variable(assigned, _) => {
                        let assigned = *assigned;
                        if words.resolve(assigned) == name {
                            if op.is_some() { return false; }
                            let bits = match prover_bit_range(walk, value, scope, words) { Some(__nikaia_value) => __nikaia_value, None => return false };
                            if bits.lo < bounds.lo || bits.hi > bounds.hi { return false; }
                        }
                    },
                    _ => { },
                }
            },
            Stmt::While { cond, .. } => { for inner in blocks_of_expr(cond) { if !prover_assigns_inside(walk, inner, name, bounds, scope, words) { return false; } } },
            Stmt::For { iter, .. } => { for inner in blocks_of_expr(iter) { if !prover_assigns_inside(walk, inner, name, bounds, scope, words) { return false; } } },
            _ => { },
        }
        for inner in blocks_of_stmt(&stmt.node) { if !prover_assigns_inside(walk, inner, name, bounds, scope, words) { return false; } }
    }
    true
}

pub(crate) fn prover_readers(program: &Program, words: &winnow_grammar::InternerContext) -> collections::BTreeSet<String> {
    let mut readers: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, receiver, args, .. } => {
                let name = *name;
                if receiver.is_none() {
                    let mut reads = true;
                    for arg in args.iter() { if arg.mutable { reads = false; } }
                    if reads && name.is_some() { readers.insert(words.resolve(match name { Some(__nikaia_value) => __nikaia_value, None => return readers }).to_owned()); }
                }
            },
            _ => { },
        }
    }
    readers
}

